"""User use cases."""

from taskapp.errors import NotFoundError
from taskapp.models_generated import User
from taskapp.storage.repository import get_repo


def get_user_or_404(store, user_id: int) -> User:
    user = get_repo(store, "users").get(user_id)
    if user is None:
        raise ValueError(f"user {user_id} not found")
    return user


def list_users(store) -> list[User]:
    return get_repo(store, "users").all()

"""Input validation."""

from taskapp.constants import MAX_TITLE_LENGTH, PRIORITY_MAX, PRIORITY_MIN, TASK_STATUSES
from taskapp.errors import ValidationError
from taskapp.utils.text import normalize_title


def validate_title(raw) -> str:
    if not isinstance(raw, str):
        raise ValidationError("title must be a string", code="INVALID_TITLE")
    title = normalize_title(raw)
    if not title or len(title) > MAX_TITLE_LENGTH:
        raise ValidationError("title length out of range", code="INVALID_TITLE")
    return title


def validate_priority(raw) -> int:
    if not isinstance(raw, int) or isinstance(raw, bool) or not PRIORITY_MIN <= raw <= PRIORITY_MAX:
        raise ValidationError("priority out of range", code="INVALID_PRIORITY")
    return raw


def validate_status(raw) -> str:
    if raw not in TASK_STATUSES:
        raise ValidationError("unknown status", code="INVALID_STATUS")
    return raw


def validate_comment_body(raw) -> str:
    if not isinstance(raw, str) or not raw.strip() or len(raw) > 2000:
        raise ValidationError("comment body length out of range", code="INVALID_COMMENT")
    return raw.strip()

"""Application errors. Every expected failure is raised as an AppError subclass."""

from taskapp.constants import HTTP_CONFLICT, HTTP_FORBIDDEN, HTTP_NOT_FOUND, HTTP_UNPROCESSABLE


class AppError(Exception):
    status = HTTP_UNPROCESSABLE
    code = "APP_ERROR"

    def __init__(self, message: str, *, code: str | None = None) -> None:
        super().__init__(message)
        if code is not None:
            self.code = code


class NotFoundError(AppError):
    status = HTTP_NOT_FOUND
    code = "NOT_FOUND"


class ValidationError(AppError):
    status = HTTP_UNPROCESSABLE
    code = "VALIDATION_ERROR"


class ConflictError(AppError):
    status = HTTP_CONFLICT
    code = "CONFLICT"


class PermissionDeniedError(AppError):
    status = HTTP_FORBIDDEN
    code = "PERMISSION_DENIED"

"""Project use cases."""

from taskapp.errors import NotFoundError
from taskapp.models_generated import Project
from taskapp.services.users import get_user_or_404
from taskapp.services.validation import validate_title
from taskapp.storage.repository import get_repo


def get_project_or_404(store, project_id: int) -> Project:
    project = get_repo(store, "projects").get(project_id)
    if project is None:
        raise NotFoundError(f"project {project_id} not found", code="PROJECT_NOT_FOUND")
    return project


def list_projects(store) -> list[Project]:
    return get_repo(store, "projects").all()


def create_project(store, name, owner_id: int) -> Project:
    get_user_or_404(store, owner_id)
    clean = validate_title(name)
    return get_repo(store, "projects").add(lambda i: Project(id=i, name=clean, owner_id=owner_id))


def archive_project(store, project_id: int) -> Project:
    project = get_project_or_404(store, project_id)
    project.archived = True
    return get_repo(store, "projects").save(project)

"""Task use cases."""

from taskapp.constants import DEFAULT_PAGE_SIZE, DEFAULT_PRIORITY
from taskapp.errors import ConflictError, NotFoundError
from taskapp.models_generated import Task
from taskapp.services.pagination import Page, paginate
from taskapp.services.projects import get_project_or_404
from taskapp.services.validation import validate_priority, validate_status, validate_title
from taskapp.storage.repository import get_repo


def get_task_or_404(store, task_id: int) -> Task:
    task = get_repo(store, "tasks").get(task_id)
    if task is None:
        raise NotFoundError(f"task {task_id} not found", code="TASK_NOT_FOUND")
    return task


def tasks_for_project(store, project_id: int) -> list[Task]:
    get_project_or_404(store, project_id)
    return [task for task in get_repo(store, "tasks").all() if task.project_id == project_id]


def create_task(store, project_id: int, title, priority=DEFAULT_PRIORITY) -> Task:
    project = get_project_or_404(store, project_id)
    if project.archived:
        raise ConflictError("project is archived", code="PROJECT_ARCHIVED")
    clean_title = validate_title(title)
    clean_priority = validate_priority(priority)
    return get_repo(store, "tasks").add(
        lambda i: Task(id=i, project_id=project_id, title=clean_title, priority=clean_priority)
    )


def update_task(store, task_id: int, changes: dict) -> Task:
    task = get_task_or_404(store, task_id)
    if "title" in changes:
        task.title = validate_title(changes["title"])
    if "status" in changes:
        task.status = validate_status(changes["status"])
    if "priority" in changes:
        task.priority = validate_priority(changes["priority"])
    return get_repo(store, "tasks").save(task)


def search_tasks(store, query: str, page: int = 1, page_size: int = DEFAULT_PAGE_SIZE) -> Page:
    needle = query.strip().lower()
    matches = [task for task in get_repo(store, "tasks").all() if needle in task.title.lower()]
    return paginate(matches, page=page, page_size=page_size)

